import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Сервис-деск офиса: заявки в ИТ и хозяйственную службу"}>
      <p>{"Офис на 120 человек на двух этажах. Сотрудники пишут о поломках кому попало: не работает принтер, нужен новый ноутбук, течёт кондиционер, нужен пропуск для гостя. Нужен внутренний сервис-деск: сотрудник входит по корпоративной почте, создаёт заявку, выбирает категорию (ИТ, хозяйственная служба, доступы), описывает проблему, прикладывает фото и указывает кабинет. По категории заявка попадает в очередь нужной службы, диспетчер назначает исполнителя и приоритет. У приоритета свои сроки реакции и решения: критичный — 1 час и 4 часа, обычный — 4 часа и 2 рабочих дня. Если срок вышел, заявка эскалируется руководителю службы. Исполнитель меняет статус, пишет комментарии и может запросить уточнение у автора — тогда отсчёт срока ставится на паузу. После закрытия автор оценивает работу от 1 до 5. Сотрудник видит только свои заявки. Отчёт: заявки по категориям, доля закрытых в срок, средняя оценка по исполнителям. Сейчас заявки ИТ вручную разбирает подрядчик клиент, дежурный номер подрядчика клиент."}</p>
      <ul>
        <li>{"Маршрутизация по категории"}</li>
        <li>{"Сроки реакции и решения по приоритету"}</li>
        <li>{"Эскалация при просрочке"}</li>
        <li>{"Пауза при запросе уточнения"}</li>
        <li>{"Фото к заявке"}</li>
        <li>{"Оценка от 1 до 5"}</li>
        <li>{"Отчёт по доле в срок"}</li>
      </ul>
      <p>{"Просроченная заявка эскалируется руководителю"}</p>
      <p>{"Сотрудник видит только свои заявки"}</p>
      <p>{"Ожидание уточнения останавливает отсчёт срока"}</p>
      <p>{"Оценку ставит только автор закрытой заявки"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
